mapper.select:
select sc.* from Stylist_Schedules sc
join Stylists st on st.stylist_id = sc.stylist_id
where st.salon_id = #{salonId} and sc.date = #{date}

mapper.update:
update Stylist_Schedules
set start_time = #{startTime}, end_time = #{endTime}, is_available = #{isAvailable}
where schedule_id = #{scheduleId}
